import * as preact from 'preact';
import * as hooks from 'preact/hooks';
import * as debug from 'preact/debug';
import * as compat from 'preact/compat';
import * as htm from 'htm';
import * as htmPreact from 'htm/preact';
import * as preactCustomElement from 'preact-custom-element';
import * as preactSignals from '@preact/signals';
import * as preactSignalsCore from '@preact/signals-core';

let modules = {};
let moduleCache = {
	preact,
	'preact/hooks': hooks,
	'preact/debug': debug,
	'preact/compat': compat,
	react: compat,
	'react-dom': compat,
	htm,
	'@preact/signals': preactSignals,
	'@preact/signals-core': preactSignalsCore,
	'htm/preact': htmPreact,
	'preact-custom-element': preactCustomElement
};

window._require = function (id) {
	// flatten unpkg
	if (typeof id === 'string') {
		id = id.replace(/(^(https?:)?\/\/unpkg\.com\/|\?module$)/gi, '');
	}
	if (id in moduleCache) {
		return moduleCache[id];
	}
	if (id in modules) {
		return (moduleCache[id] = modules[id]());
	}
	throw Error(`No module found for ${id}`);
};

import fs from 'fs/promises';
import fsSync from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { parseFrontmatter, cleanReplComments } from '../src/lib/frontmatter.js';
import { docPages } from '../src/route-config.js';
import englishTranslations from '../src/locales/en.json' with { type: 'json' };

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Read all markdown files from the guide directory
 * @param {string} guideDir
 * @returns {Promise<Array<{filename: string, content: string}>>}
 */
async function readMarkdownFiles(guideDir) {
	const files = await fs.readdir(guideDir);
	const markdownFiles = files.filter((file) => file.endsWith('.md'));

	return Promise.all(
		markdownFiles.map(async (filename) => {
			const filePath = path.join(guideDir, filename);
			const content = await fs.readFile(filePath, 'utf-8');
			return { filename, content };
		})
	);
}

/**
 * Generate the llms.txt content
 * @param {Array<{filename: string, content: string}>} files
 * @returns {string}
 */
function generateLlmsTxt(files) {
	const header = `# Preact Documentation

This file contains comprehensive documentation for Preact v10, a fast 3kB alternative to React with the same modern API.
Preact is a fast, lightweight alternative to React that provides the same modern API in a much smaller package. This documentation covers all aspects of Preact v10, including components, hooks, server-side rendering, TypeScript support, and more.

---

`;

	let content = header;

	for (const section in docPages.v10) {
		content += `## ${englishTranslations.sidebarSections[section]}\n\n`;

		for (const route in docPages.v10[section]) {
			const { filename, content: fileContent } = files.find(
				(file) => file.filename === `${route.replace('/', '')}.md`
			);

			const { description, body } = parseFrontmatter(fileContent, filename);
			let cleanedBody = cleanReplComments(body);

			// Remove <toc></toc> tags
			cleanedBody = cleanedBody.replace(/<toc><\/toc>/g, '');

			// Clean up multiple consecutive newlines and empty lines around separators
			cleanedBody = cleanedBody.replace(/\n{3,}/g, '\n\n');
			cleanedBody = cleanedBody.replace(/---\s*\n\s*\n\s*---/g, '');

			// Fix heading hierarchy: page headings should be 3 levels deep to accommodate
			// the llms document heading & the section headings for page/concept groups.
			cleanedBody = cleanedBody
				.replace(/^#### /gm, '###### ')
				.replace(/^### /gm, '##### ')
				.replace(/^## /gm, '#### ')
				// Not `/g` as there should only be one top-level heading per file
				// and this would conflict with bash comments that we have in a few places.
				.replace(/^# /m, '### ');

			if (description) {
				content += `**Description:** ${description}\n\n`;
			}

			content += `${cleanedBody}\n\n`;
			content += `------\n\n`;
		}
	}

	return content;
}

/**
 * Vite plugin to generate llms.txt from Preact documentation
 * @param {Object} options
 * @param {string} [options.guideDir] - Path to the guide directory
 * @param {string} [options.outputFile] - Path to the output file
 * @returns {import('vite').Plugin}
 */
export default function generateLlmsTxtPlugin(options = {}) {
	const guideDir =
		options.guideDir ||
		path.join(__dirname, '..', 'content', 'en', 'guide', 'v10');

	return {
		name: 'generate-llms-txt',
		apply: 'build',
		async buildStart() {
			try {
				if (!fsSync.existsSync(guideDir)) {
					this.warn(`Guide directory not found: ${guideDir}`);
					return;
				}

				const files = await readMarkdownFiles(guideDir);
				const llmsTxtContent = generateLlmsTxt(files);

				this.emitFile({
					type: 'asset',
					fileName: 'llms.txt',
					source: llmsTxtContent
				});
			} catch (error) {
				this.error(`Error generating llms.txt: ${error.message}`);
			}
		}
	};
}

import { render } from 'preact';
import { useRef } from 'preact/hooks';
import { lazy, ErrorBoundary } from 'preact-iso';
import style from './style.module.css';
import config from '../../config.json' with { type: 'json' };

const DocSearch = lazy(() =>
	import('@docsearch/react').then((m) => m.DocSearch)
);
const DocSearchStylesURL = new URL(
	'@docsearch/css/dist/style.css',
	import.meta.url
).href;

/**
 * Inject Docsearch styles into the document head above app styles,
 * solving some specificity issues w/ Vite's default lazy loading of CSS.
 */
function injectDocsearchCSS() {
	if (document.querySelector(`link[href="${DocSearchStylesURL}"]`)) return;

	const link = document.createElement('link');
	link.rel = 'stylesheet';
	link.crossOrigin = '';
	link.href = DocSearchStylesURL;
	document.head.insertAdjacentElement('afterbegin', link);
}

/**
 * Wait for Docsearch to initialize so we can trigger a click if the user
 * interacted with the placeholder button prior to Docsearch fully loading.
 *
 * @param {HTMLElement} root
 * @returns {Promise<HTMLButtonElement>}
 */
function waitForDocsearch(root) {
	return new Promise((resolve) => {
		/** @returns {HTMLButtonElement | null} */
		const getDocSearchButton = () =>
			document.querySelector('.DocSearch.DocSearch-Button');

		// Not included in the initial render, as we always style it w/ `display: none`,
		// so useful as a marker for whether DocSearch has been initialized.
		let target = root.querySelector('.DocSearch-Button-Keys');
		if (target) return resolve(getDocSearchButton());

		const observer = new MutationObserver(() => {
			target = getDocSearchButton();
			if (target) {
				observer.disconnect();
				resolve(getDocSearchButton());
			}
		});

		observer.observe(root, { childList: true, subtree: true });
	});
}

// Might be a problem with the Algolia data, but it seemingly
// appends `#app` to all URLs without a hash fragment.
//
// It also returns the full prod URL, which isn't ideal for dev/staging
const transformItems = (items) =>
	items.map((i) => {
		const url = new URL(i.url);
		return Object.assign(i, {
			url: url.pathname + url.hash.replace(/#app$/, '')
		});
	});

export default function Search() {
	const root = useRef(null);
	const rendered = useRef(false);
	const interactedWith = useRef(false);

	const loadDocSearch = () => {
		if (!rendered.current) {
			injectDocsearchCSS();
			render(
				<ErrorBoundary>
					<DocSearch
						apiKey=[REDACTED]}
						indexName={config.docsearch.indexName}
						appId={config.docsearch.appId}
						transformItems={transformItems}
					/>
				</ErrorBoundary>,
				root.current
			);

			waitForDocsearch(root.current).then((docsearchButton) => {
				rendered.current = true;
				document.querySelector('loading-bar')?.removeAttribute('showing');
				if (interactedWith.current) {
					docsearchButton.click();
				}
			});
		}
	};

	// Is `onClick` the only one we need? Enter key will trigger `click` events too on buttons
	const onInteraction = () => {
		interactedWith.current = true;

		if (!rendered.current) {
			// The <loading-bar> is sat alongside the router & has it's state controlled by it,
			// so while we could create a new context to be able to set it here, direct DOM
			// manipulation is a heck of a lot simpler.
			document.querySelector('loading-bar')?.setAttribute('showing', 'true');
		}
	};

	return (
		<div class={style.search} ref={root}>
			{rendered.current ? (
				<ErrorBoundary>
					<DocSearch
						apiKey=[REDACTED]}
						indexName={config.docsearch.indexName}
						appId={config.docsearch.appId}
						transformItems={transformItems}
					/>
				</ErrorBoundary>
			) : (
				/* Copy/paste of the HTML DocSearch normally generates, used as a placeholder */
				<button
					type="button"
					aria-label="Search"
					class="DocSearch DocSearch-Button"
					onMouseOver={loadDocSearch}
					onTouchStart={loadDocSearch}
					onFocus={loadDocSearch}
					onClick={onInteraction}
				>
					<span class="DocSearch-Button-Container">
						<span class="DocSearch-Button-Placeholder">Search</span>
					</span>
				</button>
			)}
		</div>
	);
}

import { useState } from 'preact/hooks';

export const localStorageGet = (key) => {
	try {
		return localStorage.getItem(key);
	} catch {
		return null;
	}
};

export const localStorageSet = (key, value) => {
	try {
		localStorage.setItem(key, value);
	} catch {}
};

/**
 * Automatically sync a value to localStorage
 * @param {string} key The key to store the data in
 * @param {any} initial Initial value when no localStorage entry was found
 * @param {boolean} [force] Ignore stored value, use initial instead
 * @returns {[any, (v: any) => void]}
 */
export function useStoredValue(key, initial, force) {
	let stored = localStorageGet(key);
	if (force || stored == null) stored = initial;

	const [value, setValue] = useState(stored);

	function setStoredValue(v) {
		localStorageSet(key, v);
		setValue(v);
	}

	return [value, setStoredValue];
}

